mapper.select:
SELECT * FROM shopwizard.tCatProdItem

    AND ProdCode = #{pProdCode}
    AND ItemCode = #{pItemCode}

        AND EXISTS (SELECT 1 FROM shopwizard.tCatProd SVC_P INNER JOIN shopwizard.tCmpShop SVC_S ON SVC_S.ShopCode = SVC_P.ShopCode
                    WHERE SVC_P.ProdCode = shopwizard.tCatProdItem.ProdCode AND SVC_S.SvcCode = #{pSvcCode})



    ORDER BY ${sidx} ${sord}
    ORDER BY ItemCode

LIMIT ${pPageOffset}, ${pPageSize}

SELECT COUNT(*) FROM shopwizard.tCatProdItem

    AND ProdCode = #{pProdCode}
    AND ItemCode = #{pItemCode}

        AND EXISTS (SELECT 1 FROM shopwizard.tCatProd SVC_P INNER JOIN shopwizard.tCmpShop SVC_S ON SVC_S.ShopCode = SVC_P.ShopCode
                    WHERE SVC_P.ProdCode = shopwizard.tCatProdItem.ProdCode AND SVC_S.SvcCode = #{pSvcCode})
